import sys

def longest_palindrome_substring(s):
    n = len(s)
    dp = [[False] * n for _ in range(n)]
    start, max_length = 0, 1

    for i in range(n):
        dp[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True
                start = i
                max_length = length

    return s[start:start + max_length]

def find_longest_palindrome(a, b):
    longest_palindromes_a = {}
    longest_palindromes_b = {}

    for i in range(len(a)):
        for j in range(i + 1, len(a) + 1):
            substring = a[i:j]
            if substring not in longest_palindromes_a:
                palindrome = longest_palindrome_substring(substring)
                longest_palindromes_a[substring] = palindrome

    for i in range(len(b)):
        for j in range(i + 1, len(b) + 1):
            substring = b[i:j]
            if substring not in longest_palindromes_b:
                palindrome = longest_palindrome_substring(substring)
                longest_palindrome_b[substring] = palindrome

    result = "-1"
    for sa in longest_palindromes_a:
        for sb in longest_palindromes_b:
            combined = sa + sb
            if combined == combined[::-1] and len(combined) > len(result):
                result = combined
            elif combined == combined[::-1] and len(combined) == len(result) and combined < result:
                result = combined

    return result

input = sys.stdin.read().strip().split('\n')
q = int(input[0])
index = 1
results = []

for _ in range(q):
    a = input[index]
    b = input[index + 1]
    index += 2
    results.append(find_longest_palindrome(a, b))

for result in results:
    print(result)
